export type {
  ShapeName,
  MotionStyle,
  MouseButton,
  CursorInteractionState,
  Point,
  MotionFrame,
  MoveToOptions,
  ClickOptions,
  MoveTarget,
} from './types'

export {
  SHAPE_SVGS,
  SHAPE_HOTSPOTS,
  SHAPE_DEFAULT_ANGLES,
} from './shapes'

export {
  createCurvedPath,
  animateAlong,
  jumpTo,
  durationForDistance,
  samplePath,
} from './motion'

export {
  createMotionStyle,
  headingToRotation,
} from './motionStyle'

export {
  createCursorInteraction,
  dispatchRealClick,
} from './interaction'

export {
  resolveElementCenter,
  resolveMoveTarget,
  TargetResolutionError,
} from './resolveTarget'

export { mountClickBurst } from './clickBurst'

export {
  createCursorController,
  DEFAULT_CURSOR_CONFIG,
} from './createCursorController'
export type {
  CursorController,
  CursorControllerConfig,
  CursorControllerOptions,
} from './createCursorController'

export type ShapeName = 'arrow' | 'pointer' | 'hand'

export type MotionStyle = 'standard' | 'dangling'

export type MouseButton = 'left' | 'right'

export type CursorInteractionState = 'idle' | 'pressing' | 'pressed'

export interface Point {
  x: number
  y: number
}

export interface MotionFrame extends Point {
  vx: number
  vy: number
  headingRad: number
  progress: number
}

export interface MoveToOptions {
  animate?: boolean
  duration?: number
}

export interface ClickOptions {
  button?: MouseButton
  real?: boolean
  animate?: boolean
  move?: boolean
  delayMs?: number
  /** Show the radiating-lines burst at the click point (default: options.clickBurst). */
  burst?: boolean
}

export type MoveTarget = string | Element | Point

import type { MotionFrame, Point } from './types'

export interface CubicBezierPath {
  p0: Point
  p1: Point
  p2: Point
  p3: Point
}

export interface SamplePathOptions {
  /** When false, skip derivative + atan2 (dangling with locked travel heading). */
  needHeading?: boolean
  /** Reuse this object instead of allocating a new MotionFrame. */
  out?: MotionFrame
}

export interface AnimateAlongOptions {
  duration: number
  /** Called every frame with sample data. */
  onFrame: (frame: MotionFrame) => void
  /** Easing function mapping linear t ∈ [0,1] → eased t. Default ease-in-out. */
  ease?: (t: number) => number
  needHeading?: boolean
  /** Optional now() for tests. */
  now?: () => number
  /** Optional rAF / cancel for tests. */
  raf?: (cb: FrameRequestCallback) => number
  caf?: (id: number) => void
}

export interface AnimateHandle {
  cancel: () => void
  finished: Promise<void>
}

function clamp(n: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, n))
}

/** Smoothstep-ish ease-in-out. */
export function easeInOutCubic(t: number): number {
  const x = clamp(t, 0, 1)
  return x < 0.5 ? 4 * x * x * x : 1 - (-2 * x + 2) ** 3 / 2
}

export function distance(a: Point, b: Point): number {
  const dx = b.x - a.x
  const dy = b.y - a.y
  return Math.hypot(dx, dy)
}

export function lerp(a: number, b: number, t: number): number {
  return a + (b - a) * t
}

/** Evaluate cubic Bézier position at t ∈ [0,1]. */
export function bezierPoint(path: CubicBezierPath, t: number): Point {
  const u = 1 - t
  const tt = t * t
  const uu = u * u
  const uuu = uu * u
  const ttt = tt * t
  return {
    x: uuu * path.p0.x + 3 * uu * t * path.p1.x + 3 * u * tt * path.p2.x + ttt * path.p3.x,
    y: uuu * path.p0.y + 3 * uu * t * path.p1.y + 3 * u * tt * path.p2.y + ttt * path.p3.y,
  }
}

/** Write cubic Bézier position into `out` (no allocation). */
export function bezierPointInto(
  path: CubicBezierPath,
  t: number,
  out: Point,
): void {
  const u = 1 - t
  const tt = t * t
  const uu = u * u
  const uuu = uu * u
  const ttt = tt * t
  out.x = uuu * path.p0.x + 3 * uu * t * path.p1.x + 3 * u * tt * path.p2.x + ttt * path.p3.x
  out.y = uuu * path.p0.y + 3 * uu * t * path.p1.y + 3 * u * tt * path.p2.y + ttt * path.p3.y
}

/** First derivative of cubic Bézier (velocity direction). */
export function bezierDerivative(path: CubicBezierPath, t: number): Point {
  const u = 1 - t
  return {
    x:
      3 * u * u * (path.p1.x - path.p0.x) +
      6 * u * t * (path.p2.x - path.p1.x) +
      3 * t * t * (path.p3.x - path.p2.x),
    y:
      3 * u * u * (path.p1.y - path.p0.y) +
      6 * u * t * (path.p2.y - path.p1.y) +
      3 * t * t * (path.p3.y - path.p2.y),
  }
}

/**
 * Build a cubic Bézier from `from` → `to` with slightly randomized control
 * points so motion feels like a human hand rather than a straight line.
 */
export function createCurvedPath(
  from: Point,
  to: Point,
  random: () => number = Math.random,
): CubicBezierPath {
  const dx = to.x - from.x
  const dy = to.y - from.y
  const dist = Math.hypot(dx, dy) || 1
  const nx = -dy / dist
  const ny = dx / dist

  const jitterScale = dist * (0.15 + random() * 0.2)
  const side = random() < 0.5 ? -1 : 1
  const j1 = side * jitterScale * (0.6 + random() * 0.4)
  const j2 = side * jitterScale * (0.4 + random() * 0.5) * (random() < 0.5 ? -1 : 1)

  const t1 = 0.25 + random() * 0.15
  const t2 = 0.6 + random() * 0.2

  return {
    p0: { x: from.x, y: from.y },
    p1: {
      x: from.x + dx * t1 + nx * j1,
      y: from.y + dy * t1 + ny * j1,
    },
    p2: {
      x: from.x + dx * t2 + nx * j2,
      y: from.y + dy * t2 + ny * j2,
    },
    p3: { x: to.x, y: to.y },
  }
}

/** Duration in ms from distance, clamped. */
export function durationForDistance(
  dist: number,
  minDuration = 280,
  maxDuration = 900,
  pxPerMs = 1.1,
): number {
  return clamp(dist / pxPerMs, minDuration, maxDuration)
}

const sharedFrame: MotionFrame = {
  x: 0,
  y: 0,
  vx: 0,
  vy: 0,
  headingRad: 0,
  progress: 0,
}

export function samplePath(
  path: CubicBezierPath,
  t: number,
  progress: number,
  options: SamplePathOptions = {},
): MotionFrame {
  const out = options.out ?? sharedFrame
  const needHeading = options.needHeading !== false

  bezierPointInto(path, t, out)
  out.progress = progress

  if (needHeading) {
    const deriv = bezierDerivative(path, t)
    out.vx = deriv.x
    out.vy = deriv.y
    out.headingRad = Math.atan2(deriv.y, deriv.x)
  } else {
    out.vx = 0
    out.vy = 0
    out.headingRad = 0
  }

  return out
}

/**
 * Animate along a cubic path with rAF. Returns a cancelable handle.
 */
export function animateAlong(path: CubicBezierPath, options: AnimateAlongOptions): AnimateHandle {
  const ease = options.ease ?? easeInOutCubic
  const now = options.now ?? (() => performance.now())
  const raf = options.raf ?? ((cb) => requestAnimationFrame(cb))
  const caf = options.caf ?? ((id) => cancelAnimationFrame(id))
  const needHeading = options.needHeading !== false
  const frame = sharedFrame

  let cancelled = false
  let frameId = 0
  const start = now()

  let resolveFinished!: () => void
  const finished = new Promise<void>((resolve) => {
    resolveFinished = resolve
  })

  const tick = (time: number) => {
    if (cancelled) {
      resolveFinished()
      return
    }
    const elapsed = time - start
    const linear = options.duration <= 0 ? 1 : clamp(elapsed / options.duration, 0, 1)
    const eased = ease(linear)
    options.onFrame(samplePath(path, eased, linear, { needHeading, out: frame }))

    if (linear < 1) {
      frameId = raf(tick)
    } else {
      resolveFinished()
    }
  }

  // Seed first frame immediately at t=0
  options.onFrame(samplePath(path, 0, 0, { needHeading, out: frame }))
  frameId = raf(tick)

  return {
    cancel() {
      if (cancelled) return
      cancelled = true
      caf(frameId)
      resolveFinished()
    },
    finished,
  }
}

/** Instant jump (no animation). */
export function jumpTo(to: Point, onFrame: (frame: MotionFrame) => void): void {
  sharedFrame.x = to.x
  sharedFrame.y = to.y
  sharedFrame.vx = 0
  sharedFrame.vy = 0
  sharedFrame.headingRad = 0
  sharedFrame.progress = 1
  onFrame(sharedFrame)
}


export function useCursorMotion() {
  return {
    createCurvedPath,
    animateAlong,
    jumpTo,
    durationForDistance,
    samplePath,
    easeInOutCubic,
    distance,
    lerp,
  }
}

import type { MotionFrame, MotionStyle, Point } from './types'

export interface CreateMotionStyleOptions {
  /**
   * Tip orientation at CSS rotate(0), as offset from pointing **up** (degrees).
   * Hand (finger up) = 0; arrow/pointer (tip up-left) ≈ -45.
   */
  getDefaultAngle?: () => number
  defaultAngle?: number
  /** How quickly rotation chases the travel heading (0–1). */
  spring?: number
  /** Resting CSS rotation when idle (usually 0). */
  restDeg?: number
  /** Speed (px/frame-ish) below which follow motion settles upright. */
  settleSpeed?: number
  /** Called whenever rotation changes (for imperative paint). */
  onRotation?: (deg: number) => void
}

function radToDeg(rad: number): number {
  return (rad * 180) / Math.PI
}

/** Normalize to (-180, 180] so spring lerp takes the shortest turn. */
export function normalizeDeg(deg: number): number {
  return ((deg + 540) % 360) - 180
}

function lerpAngle(from: number, to: number, t: number): number {
  const diff = ((to - from + 540) % 360) - 180
  return from + diff * t
}

/**
 * CSS rotation that aims the tip along `headingRad` (screen atan2: 0=east, 90=down).
 */
export function headingToRotation(
  headingRad: number,
  defaultAngle = 0,
): number {
  return normalizeDeg(radToDeg(headingRad) + 90 - defaultAngle)
}

/** @deprecated Use headingToRotation */
export function headingToTilt(
  headingRad: number,
  _maxTilt: number,
  defaultAngle = 0,
): number {
  return headingToRotation(headingRad, defaultAngle)
}

/**
 * `standard` keeps rotation at restDeg (0).
 * `dangling` rotates so the tip points along travel.
 */
export function createMotionStyle(
  getStyle: () => MotionStyle,
  options: CreateMotionStyleOptions = {},
) {
  const spring = options.spring ?? 0.22
  const restDeg = options.restDeg ?? 0
  const settleSpeed = options.settleSpeed ?? 1.2

  let rotationDeg = restDeg
  let settling = false
  let travelHeadingRad: number | null = null
  let settleRaf = 0

  function getDefaultAngle(): number {
    if (options.getDefaultAngle) return options.getDefaultAngle()
    return options.defaultAngle ?? 0
  }

  function setRotation(deg: number): void {
    rotationDeg = deg
    options.onRotation?.(deg)
  }

  function cancelSettleLoop() {
    if (settleRaf) {
      cancelAnimationFrame(settleRaf)
      settleRaf = 0
    }
  }

  function angleError(from: number, to: number): number {
    return ((from - to + 540) % 360) - 180
  }

  function startSettleLoop(): void {
    if (getStyle() !== 'dangling') {
      setRotation(restDeg)
      travelHeadingRad = null
      settling = false
      return
    }
    settling = true
    travelHeadingRad = null
    cancelSettleLoop()

    const tick = () => {
      if (!settling || getStyle() !== 'dangling') {
        settleRaf = 0
        return
      }
      const next = lerpAngle(rotationDeg, restDeg, Math.min(1, spring * 1.6))
      setRotation(next)
      if (Math.abs(angleError(rotationDeg, restDeg)) < 0.4) {
        setRotation(restDeg)
        settling = false
        settleRaf = 0
        return
      }
      settleRaf = requestAnimationFrame(tick)
    }
    settleRaf = requestAnimationFrame(tick)
  }

  function beginTravel(from: Point, to: Point): void {
    cancelSettleLoop()
    settling = false
    const dx = to.x - from.x
    const dy = to.y - from.y
    if (Math.hypot(dx, dy) > 1) {
      travelHeadingRad = Math.atan2(dy, dx)
    } else {
      travelHeadingRad = null
    }
  }

  function hasLockedTravel(): boolean {
    return travelHeadingRad != null
  }

  function isSettled(): boolean {
    return !settling && Math.abs(angleError(rotationDeg, restDeg)) < 0.4
  }

  function chaseHeading(headingRad: number): void {
    const target = headingToRotation(headingRad, getDefaultAngle())
    setRotation(lerpAngle(rotationDeg, target, spring))
  }

  function onFrame(frame: MotionFrame): void {
    if (getStyle() !== 'dangling') {
      cancelSettleLoop()
      if (rotationDeg !== restDeg) setRotation(restDeg)
      settling = false
      travelHeadingRad = null
      return
    }

    if (travelHeadingRad != null) {
      if (frame.progress >= 0.97) {
        startSettleLoop()
        return
      }
      if (settling) cancelSettleLoop()
      settling = false
      chaseHeading(travelHeadingRad)
      return
    }

    const speed = Math.hypot(frame.vx, frame.vy)
    if (speed > settleSpeed) {
      if (settling) cancelSettleLoop()
      settling = false
      chaseHeading(Math.atan2(frame.vy, frame.vx))
      return
    }

    if (!settling && Math.abs(angleError(rotationDeg, restDeg)) > 0.4) {
      startSettleLoop()
    }
  }

  function onSettle(): void {
    startSettleLoop()
  }

  function reset(): void {
    cancelSettleLoop()
    setRotation(restDeg)
    settling = false
    travelHeadingRad = null
  }

  function getRotation(): number {
    return rotationDeg
  }

  return {
    getRotation,
    hasLockedTravel,
    isSettled,
    beginTravel,
    onFrame,
    onSettle,
    reset,
  }
}

/** @deprecated Use createMotionStyle */
export const useCursorMotionStyle = createMotionStyle

import type { ClickOptions, CursorInteractionState, MouseButton } from './types'

export interface CreateCursorInteractionOptions {
  pressedScale?: number
  animationDuration?: number
  onChange?: (snapshot: CursorInteractionSnapshot) => void
}

export interface CursorInteractionSnapshot {
  state: CursorInteractionState
  button: MouseButton | null
  pressScale: number
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => setTimeout(resolve, ms))
}

function buttonCode(button: MouseButton): number {
  return button === 'right' ? 2 : 0
}

function buttonsMask(button: MouseButton): number {
  return button === 'right' ? 2 : 1
}

/**
 * Dispatch a synthetic pointer/mouse click sequence at viewport coordinates.
 */
export function dispatchRealClick(
  clientX: number,
  clientY: number,
  button: MouseButton,
): void {
  const target = document.elementFromPoint(clientX, clientY)
  if (!target) {
    console.warn('pointing-cursor: no element under hotspot for real click')
    return
  }

  const down: MouseEventInit = {
    bubbles: true,
    cancelable: true,
    clientX,
    clientY,
    button: buttonCode(button),
    buttons: buttonsMask(button),
  }

  if (typeof PointerEvent !== 'undefined') {
    const pointerDown: PointerEventInit = {
      ...down,
      pointerId: 1,
      pointerType: 'mouse',
      isPrimary: true,
    }
    target.dispatchEvent(new PointerEvent('pointerdown', pointerDown))
  }
  target.dispatchEvent(new MouseEvent('mousedown', down))

  const up: MouseEventInit = { ...down, buttons: 0 }
  if (typeof PointerEvent !== 'undefined') {
    target.dispatchEvent(
      new PointerEvent('pointerup', {
        ...up,
        pointerId: 1,
        pointerType: 'mouse',
        isPrimary: true,
      }),
    )
  }
  target.dispatchEvent(new MouseEvent('mouseup', up))

  if (button === 'left') {
    target.dispatchEvent(new MouseEvent('click', up))
  } else {
    target.dispatchEvent(new MouseEvent('contextmenu', up))
  }
}

export function createCursorInteraction(
  options: CreateCursorInteractionOptions = {},
) {
  const pressedScaleAmount = options.pressedScale ?? 0.9
  const defaultDuration = () => options.animationDuration ?? 120

  let state: CursorInteractionState = 'idle'
  let button: MouseButton | null = null
  let pressScale = 1
  let pressToken = 0

  function notify(): void {
    options.onChange?.({ state, button, pressScale })
  }

  async function press(
    btn: MouseButton = 'left',
    delayMs = defaultDuration(),
  ): Promise<void> {
    const token = ++pressToken
    state = 'pressing'
    button = btn
    pressScale = pressedScaleAmount
    notify()
    await sleep(Math.max(40, delayMs))
    if (token !== pressToken) return
    state = 'pressed'
    notify()
  }

  async function release(): Promise<void> {
    pressToken += 1
    state = 'idle'
    button = null
    pressScale = 1
    notify()
  }

  async function click(
    opts: ClickOptions & { clientX?: number; clientY?: number } = {},
  ): Promise<void> {
    const btn = opts.button ?? 'left'
    const animate = opts.animate !== false
    const delayMs = opts.delayMs ?? defaultDuration()

    if (animate) {
      await press(btn, delayMs)
    } else {
      button = btn
      state = 'pressed'
      notify()
    }

    if (
      opts.real &&
      typeof opts.clientX === 'number' &&
      typeof opts.clientY === 'number'
    ) {
      dispatchRealClick(opts.clientX, opts.clientY, btn)
    }

    await release()
  }

  return {
    getState: () => state,
    getButton: () => button,
    getPressScale: () => pressScale,
    press,
    release,
    click,
  }
}

/** @deprecated Use createCursorInteraction */
export const useCursorInteraction = createCursorInteraction

import type { Point } from './types'

export class TargetResolutionError extends Error {
  constructor(message: string) {
    super(message)
    this.name = 'TargetResolutionError'
  }
}

/**
 * Resolve a CSS selector or Element to the center of its bounding box
 * in viewport coordinates.
 */
export function resolveElementCenter(target: string | Element): Point {
  const el =
    typeof target === 'string' ? document.querySelector(target) : target

  if (!el) {
    const message =
      typeof target === 'string'
        ? `pointing-cursor: no element matches selector "${target}"`
        : 'pointing-cursor: target element is null'
    console.warn(message)
    throw new TargetResolutionError(message)
  }

  const rect = el.getBoundingClientRect()
  return {
    x: rect.left + rect.width / 2,
    y: rect.top + rect.height / 2,
  }
}

/**
 * Normalize move targets: numbers as coordinates, or selector/Element as center.
 */
export function resolveMoveTarget(
  target: number | string | Element,
  y?: number,
): Point {
  if (typeof target === 'number') {
    if (typeof y !== 'number' || Number.isNaN(y)) {
      throw new TargetResolutionError(
        'pointing-cursor: moveTo(x, y) requires numeric y when x is a number',
      )
    }
    return { x: target, y }
  }
  return resolveElementCenter(target)
}

const NS = 'http://www.w3.org/2000/svg'
const STYLE_ID = 'pointing-cursor-burst-style'
const RAY_COUNT = 8
const VIEW = 32
const CX = VIEW / 2
const INNER = 5
const OUTER = 13

export interface ClickBurstRay {
  x1: number
  y1: number
  x2: number
  y2: number
}

export function computeBurstRays(): ClickBurstRay[] {
  return Array.from({ length: RAY_COUNT }, (_, i) => {
    const rad = (i * Math.PI) / 4
    const cos = Math.cos(rad)
    const sin = Math.sin(rad)
    return {
      x1: CX + cos * INNER,
      y1: CX + sin * INNER,
      x2: CX + cos * OUTER,
      y2: CX + sin * OUTER,
    }
  })
}

function ensureBurstStyles(doc: Document): void {
  if (doc.getElementById(STYLE_ID)) return
  const style = doc.createElement('style')
  style.id = STYLE_ID
  style.textContent = `
@keyframes pointing-cursor-burst-expand {
  0% { opacity: 1; transform: scale(0.35); }
  70% { opacity: 1; }
  100% { opacity: 0; transform: scale(1.35); }
}
.pointing-cursor-burst__svg {
  display: block;
  overflow: visible;
  transform-origin: 50% 50%;
  animation: pointing-cursor-burst-expand var(--pointing-cursor-burst-ms, 420ms) ease-out forwards;
}
`
  doc.head.appendChild(style)
}

export interface MountClickBurstOptions {
  x: number
  y: number
  color: string
  strokeWidth?: number | string
  size?: string
  durationMs?: number
  zIndex?: number
  onDone?: () => void
}

/**
 * Imperatively mount a radiating click-burst SVG under `parent` (usually document.body).
 */
export function mountClickBurst(
  parent: HTMLElement,
  options: MountClickBurstOptions,
): { destroy(): void } {
  const doc = parent.ownerDocument ?? document
  ensureBurstStyles(doc)

  const durationMs = options.durationMs ?? 420
  const size = options.size ?? '2.25em'
  const strokeWidth = options.strokeWidth ?? 2
  const zIndex = options.zIndex ?? 9998

  const wrap = doc.createElement('div')
  wrap.className = 'pointing-cursor-burst'
  wrap.setAttribute('aria-hidden', 'true')
  Object.assign(wrap.style, {
    position: 'fixed',
    left: `${options.x}px`,
    top: `${options.y}px`,
    zIndex: String(zIndex),
    pointerEvents: 'none',
    transform: 'translate(-50%, -50%)',
  })

  const svg = doc.createElementNS(NS, 'svg')
  svg.setAttribute('class', 'pointing-cursor-burst__svg')
  svg.setAttribute('viewBox', `0 0 ${VIEW} ${VIEW}`)
  svg.setAttribute('xmlns', NS)
  svg.setAttribute('aria-hidden', 'true')
  svg.style.width = size
  svg.style.height = size
  svg.style.setProperty('--pointing-cursor-burst-ms', `${durationMs}ms`)

  for (const ray of computeBurstRays()) {
    const line = doc.createElementNS(NS, 'line')
    line.setAttribute('x1', String(ray.x1))
    line.setAttribute('y1', String(ray.y1))
    line.setAttribute('x2', String(ray.x2))
    line.setAttribute('y2', String(ray.y2))
    line.setAttribute('stroke', options.color)
    line.setAttribute('stroke-width', String(strokeWidth))
    line.setAttribute('stroke-linecap', 'round')
    svg.appendChild(line)
  }

  wrap.appendChild(svg)
  parent.appendChild(wrap)

  let doneTimer = 0
  let destroyed = false

  function destroy(): void {
    if (destroyed) return
    destroyed = true
    if (doneTimer) window.clearTimeout(doneTimer)
    wrap.remove()
    options.onDone?.()
  }

  doneTimer = window.setTimeout(destroy, durationMs)

  return { destroy }
}

import {
  animateAlong,
  createCurvedPath,
  durationForDistance,
  jumpTo,
  type AnimateHandle,
} from './motion'
import { createMotionStyle } from './motionStyle'
import { createCursorInteraction } from './interaction'
import { resolveMoveTarget } from './resolveTarget'
import { mountClickBurst } from './clickBurst'
import {
  SHAPE_DEFAULT_ANGLES,
  SHAPE_HOTSPOTS,
  SHAPE_SVGS,
} from './shapes'
import type {
  ClickOptions,
  MotionFrame,
  MotionStyle,
  MouseButton,
  MoveToOptions,
  Point,
  ShapeName,
} from './types'

export interface CursorControllerOptions {
  getRootEl: () => HTMLElement | null
  getInnerEl: () => HTMLElement | null
  /** Host for click-burst overlays (default: document.body). */
  getBurstParent?: () => HTMLElement | null
  onMove?: (point: Point, kind: 'frame' | 'boundary') => void
  onShow?: () => void
  onHide?: () => void
  onVisibilityChange?: (visible: boolean) => void
  onInteractionChange?: (snapshot: {
    state: string
    button: MouseButton | null
    pressScale: number
    pressed: boolean
  }) => void
}

export interface CursorControllerConfig {
  size: string
  shape: ShapeName
  stroke: string
  fill: string
  visible: boolean
  followMouse: boolean
  hideNativeCursor: boolean
  x?: number
  y?: number
  hotspotX?: number
  hotspotY?: number
  zIndex: number
  minDuration: number
  maxDuration: number
  motionStyle: MotionStyle
  defaultAngle?: number
  mirrorNativeClicks: boolean
  clickAnimationDuration: number
  clickBurst: boolean
  clickBurstStrokeWidth: number | string
  clickBurstSize: string
  clickBurstDurationMs: number
  clickBurstLeftColor: string
  clickBurstRightColor: string
  clickBurstColor: string
  emitMoveFrames: boolean
}

export const DEFAULT_CURSOR_CONFIG: CursorControllerConfig = {
  size: '3em',
  shape: 'arrow',
  stroke: '#111111',
  fill: '#ffffff',
  visible: true,
  followMouse: false,
  hideNativeCursor: false,
  zIndex: 9999,
  minDuration: 280,
  maxDuration: 900,
  motionStyle: 'dangling',
  mirrorNativeClicks: true,
  clickAnimationDuration: 120,
  clickBurst: true,
  clickBurstStrokeWidth: 2,
  clickBurstSize: '2.25em',
  clickBurstDurationMs: 420,
  clickBurstLeftColor: '#22c55e',
  clickBurstRightColor: '#ef4444',
  clickBurstColor: '#111111',
  emitMoveFrames: false,
}

const MOVE_EMIT_INTERVAL_MS = 30
const FOLLOW_IDLE_MS = 100
const SUBPIXEL = 0.05

export interface CursorController {
  show(): void
  hide(): void
  isVisible(): boolean
  moveTo(
    target: number | string | Element,
    yOrOptions?: number | MoveToOptions,
    maybeOptions?: MoveToOptions,
  ): Promise<void>
  setFollow(enabled: boolean): void
  isFollowing(): boolean
  getPosition(): Point
  click(options?: ClickOptions): Promise<void>
  clickAt(
    target: number | string | Element,
    yOrOptions?: number | ClickOptions,
    maybeOptions?: ClickOptions,
  ): Promise<void>
  leftClick(options?: Omit<ClickOptions, 'button'>): Promise<void>
  rightClick(options?: Omit<ClickOptions, 'button'>): Promise<void>
  setMotionStyle(style: MotionStyle): void
  getShapeMarkup(): string
  getShapePaintStyle(): Record<string, string>
  getInteraction(): {
    pressed: boolean
    button: MouseButton | null
    pressScale: number
  }
  mount(): void
  destroy(): void
  setOptions(partial: Partial<CursorControllerConfig>): void
  getOptions(): CursorControllerConfig
  paint(): void
}

export function createCursorController(
  hooks: CursorControllerOptions,
  initial: Partial<CursorControllerConfig> = {},
): CursorController {
  let config: CursorControllerConfig = {
    ...DEFAULT_CURSOR_CONFIG,
    ...initial,
  }

  let posX = 0
  let posY = 0
  let rotationDeg = 0
  let pressScale = 1
  let visible = config.visible
  let following = false

  let motionHandle: AnimateHandle | null = null
  let followRaf = 0
  let followTarget: Point | null = null
  let lastMouseMoveAt = 0
  let nativeCursorBackup = ''
  let lastMoveEmitAt = 0
  const activeBursts: Array<{ destroy(): void }> = []

  let motionStyleValue: MotionStyle = config.motionStyle

  const motionStyleApi = createMotionStyle(() => motionStyleValue, {
    getDefaultAngle: () =>
      config.defaultAngle ?? SHAPE_DEFAULT_ANGLES[config.shape],
    onRotation(deg) {
      rotationDeg = deg
      paintInner()
    },
  })

  const interaction = createCursorInteraction({
    animationDuration: config.clickAnimationDuration,
    onChange(snapshot) {
      pressScale = snapshot.pressScale
      paintInner()
      hooks.onInteractionChange?.({
        ...snapshot,
        pressed: snapshot.state !== 'idle',
      })
    },
  })

  function hotspotFractions(): { x: number; y: number } {
    const defaults = SHAPE_HOTSPOTS[config.shape]
    return {
      x: config.hotspotX ?? defaults.x,
      y: config.hotspotY ?? defaults.y,
    }
  }

  function paintOuter(): void {
    const el = hooks.getRootEl()
    if (!el) return
    const h = hotspotFractions()
    el.style.transform = `translate3d(${posX}px, ${posY}px, 0) translate(-${h.x * 100}%, -${h.y * 100}%)`
  }

  function paintInner(): void {
    const el = hooks.getInnerEl()
    if (!el) return
    const h = hotspotFractions()
    el.style.transformOrigin = `${h.x * 100}% ${h.y * 100}%`
    el.style.transform = `rotate(${rotationDeg}deg) scale(${pressScale})`
  }

  function paint(): void {
    paintOuter()
    paintInner()
  }

  function emitMove(kind: 'frame' | 'boundary'): void {
    if (kind === 'frame') {
      if (!config.emitMoveFrames) return
      const now = performance.now()
      if (now - lastMoveEmitAt < MOVE_EMIT_INTERVAL_MS) return
      lastMoveEmitAt = now
    }
    hooks.onMove?.({ x: posX, y: posY }, kind)
  }

  function applyFrame(
    frame: MotionFrame,
    opts?: { emitBoundary?: boolean },
  ): void {
    posX = frame.x
    posY = frame.y
    motionStyleApi.onFrame(frame)
    paint()
    if (opts?.emitBoundary) emitMove('boundary')
    else emitMove('frame')
  }

  function cancelMotion() {
    motionHandle?.cancel()
    motionHandle = null
  }

  function burstColorFor(button: MouseButton): string {
    if (button === 'right') return config.clickBurstRightColor
    if (button === 'left') return config.clickBurstLeftColor
    return config.clickBurstColor
  }

  function spawnBurst(button: MouseButton, at?: Point) {
    if (!config.clickBurst) return
    const parent =
      hooks.getBurstParent?.() ??
      (typeof document !== 'undefined' ? document.body : null)
    if (!parent) return
    const handle = mountClickBurst(parent, {
      x: at?.x ?? posX,
      y: at?.y ?? posY,
      color: burstColorFor(button),
      strokeWidth: config.clickBurstStrokeWidth,
      size: config.clickBurstSize,
      durationMs: config.clickBurstDurationMs,
      zIndex: config.zIndex - 1,
      onDone: () => {
        const i = activeBursts.indexOf(handle)
        if (i >= 0) activeBursts.splice(i, 1)
      },
    })
    activeBursts.push(handle)
  }

  function show() {
    visible = true
    hooks.onVisibilityChange?.(true)
    hooks.onShow?.()
  }

  function hide() {
    visible = false
    hooks.onVisibilityChange?.(false)
    hooks.onHide?.()
  }

  async function moveTo(
    target: number | string | Element,
    yOrOptions?: number | MoveToOptions,
    maybeOptions?: MoveToOptions,
  ): Promise<void> {
    let point: Point
    let options: MoveToOptions = {}

    if (typeof target === 'number') {
      point = resolveMoveTarget(target, yOrOptions as number)
      options = maybeOptions ?? {}
    } else {
      point = resolveMoveTarget(target)
      options = (yOrOptions as MoveToOptions | undefined) ?? {}
    }

    cancelMotion()

    const animate = options.animate !== false
    if (!animate) {
      jumpTo(point, (f) => applyFrame(f, { emitBoundary: true }))
      motionStyleApi.onSettle()
      return
    }

    const from = { x: posX, y: posY }
    const dist = Math.hypot(point.x - from.x, point.y - from.y)
    const duration =
      options.duration ??
      durationForDistance(dist, config.minDuration, config.maxDuration)
    const path = createCurvedPath(from, point)

    motionStyleApi.beginTravel(from, point)
    emitMove('boundary')

    const needHeading =
      motionStyleValue !== 'dangling' || !motionStyleApi.hasLockedTravel()

    motionHandle = animateAlong(path, {
      duration,
      needHeading,
      onFrame: applyFrame,
    })
    await motionHandle.finished
    motionHandle = null
    motionStyleApi.onSettle()
    emitMove('boundary')
  }

  function onNativeMouseDown(event: MouseEvent) {
    if (!config.mirrorNativeClicks || !following) return
    if (event.button !== 0 && event.button !== 2) return
    const button: MouseButton = event.button === 2 ? 'right' : 'left'
    spawnBurst(button, { x: event.clientX, y: event.clientY })
    void interaction.press(button, config.clickAnimationDuration)
  }

  function onNativeMouseUp() {
    if (!config.mirrorNativeClicks || !following) return
    void interaction.release()
  }

  function onMouseMove(event: MouseEvent) {
    if (!following) return
    followTarget = { x: event.clientX, y: event.clientY }
    lastMouseMoveAt = performance.now()
    if (!followRaf) {
      followRaf = requestAnimationFrame(followTick)
    }
  }

  function followTick() {
    if (!following) {
      followRaf = 0
      return
    }

    const now = performance.now()
    const idle = now - lastMouseMoveAt > FOLLOW_IDLE_MS

    if (followTarget) {
      const dx = followTarget.x - posX
      const dy = followTarget.y - posY
      const moved = Math.abs(dx) > SUBPIXEL || Math.abs(dy) > SUBPIXEL

      if (moved) {
        posX += dx * 0.45
        posY += dy * 0.45
        motionStyleApi.onFrame({
          x: posX,
          y: posY,
          vx: dx,
          vy: dy,
          headingRad: Math.atan2(dy, dx),
          progress: 0,
        })
        paint()
        emitMove('frame')
      } else if (!idle) {
        motionStyleApi.onFrame({
          x: posX,
          y: posY,
          vx: 0,
          vy: 0,
          headingRad: 0,
          progress: 0,
        })
      }
    }

    if (idle && motionStyleApi.isSettled()) {
      followRaf = 0
      return
    }

    followRaf = requestAnimationFrame(followTick)
  }

  function startFollowLoop() {
    lastMouseMoveAt = performance.now()
    window.addEventListener('mousemove', onMouseMove, { passive: true })
    window.addEventListener('mousedown', onNativeMouseDown, true)
    window.addEventListener('mouseup', onNativeMouseUp, true)
    if (!followRaf) {
      followRaf = requestAnimationFrame(followTick)
    }
  }

  function stopFollowLoop() {
    window.removeEventListener('mousemove', onMouseMove)
    window.removeEventListener('mousedown', onNativeMouseDown, true)
    window.removeEventListener('mouseup', onNativeMouseUp, true)
    if (followRaf) {
      cancelAnimationFrame(followRaf)
      followRaf = 0
    }
    followTarget = null
    void interaction.release()
  }

  function applyNativeCursorHide() {
    if (!config.hideNativeCursor || typeof document === 'undefined') return
    if (!nativeCursorBackup) {
      nativeCursorBackup = document.documentElement.style.cursor
    }
    document.documentElement.style.cursor = 'none'
  }

  function restoreNativeCursor() {
    if (typeof document === 'undefined') return
    if (
      nativeCursorBackup !== '' ||
      document.documentElement.style.cursor === 'none'
    ) {
      document.documentElement.style.cursor = nativeCursorBackup
      nativeCursorBackup = ''
    }
  }

  function setFollow(enabled: boolean) {
    following = enabled
    if (!enabled) {
      stopFollowLoop()
      restoreNativeCursor()
      motionStyleApi.onSettle()
    } else {
      startFollowLoop()
      applyNativeCursorHide()
    }
  }

  async function click(options: ClickOptions = {}): Promise<void> {
    const button = options.button ?? 'left'
    const showBurst = options.burst ?? config.clickBurst
    if (showBurst) spawnBurst(button)

    await interaction.click({
      ...options,
      button,
      delayMs: options.delayMs ?? config.clickAnimationDuration,
      clientX: posX,
      clientY: posY,
    })
  }

  async function clickAt(
    target: number | string | Element,
    yOrOptions?: number | ClickOptions,
    maybeOptions?: ClickOptions,
  ): Promise<void> {
    let point: Point
    let options: ClickOptions = {}

    if (typeof target === 'number') {
      point = resolveMoveTarget(target, yOrOptions as number)
      options = maybeOptions ?? {}
    } else {
      point = resolveMoveTarget(target)
      options = (yOrOptions as ClickOptions | undefined) ?? {}
    }

    if (options.move !== false) {
      await moveTo(point.x, point.y, { animate: options.animate !== false })
    } else {
      jumpTo(point, (f) => applyFrame(f, { emitBoundary: true }))
    }

    await click(options)
  }

  function setMotionStyle(style: MotionStyle) {
    motionStyleValue = style
    config = { ...config, motionStyle: style }
    if (style === 'standard') motionStyleApi.reset()
  }

  function setOptions(partial: Partial<CursorControllerConfig>): void {
    const prev = config
    config = { ...config, ...partial }

    if (
      partial.clickAnimationDuration != null &&
      partial.clickAnimationDuration !== prev.clickAnimationDuration
    ) {
      // duration is read via closure on each press; config is enough
    }

    if (partial.motionStyle != null && partial.motionStyle !== motionStyleValue) {
      setMotionStyle(partial.motionStyle)
    }

    if (partial.visible != null && partial.visible !== visible) {
      if (partial.visible) show()
      else hide()
    }

    if (partial.followMouse != null && partial.followMouse !== following) {
      setFollow(partial.followMouse)
    } else if (partial.hideNativeCursor != null) {
      if (partial.hideNativeCursor && following) applyNativeCursorHide()
      else if (!partial.hideNativeCursor) restoreNativeCursor()
    }

    if (
      typeof partial.x === 'number' &&
      typeof partial.y === 'number' &&
      !following &&
      (partial.x !== prev.x || partial.y !== prev.y)
    ) {
      void moveTo(partial.x, partial.y)
    }

    paint()
  }

  function mount(): void {
    if (typeof config.x === 'number' && typeof config.y === 'number') {
      jumpTo({ x: config.x, y: config.y }, (f) =>
        applyFrame(f, { emitBoundary: true }),
      )
    } else if (typeof window !== 'undefined') {
      jumpTo(
        { x: window.innerWidth / 2, y: window.innerHeight / 2 },
        (f) => applyFrame(f, { emitBoundary: true }),
      )
    } else {
      paint()
    }
    if (config.followMouse) {
      setFollow(true)
    }
    hooks.onVisibilityChange?.(visible)
  }

  function destroy(): void {
    cancelMotion()
    stopFollowLoop()
    restoreNativeCursor()
    for (const b of activeBursts.splice(0)) b.destroy()
  }

  return {
    show,
    hide,
    isVisible: () => visible,
    moveTo,
    setFollow,
    isFollowing: () => following,
    getPosition: () => ({ x: posX, y: posY }),
    click,
    clickAt,
    leftClick: (o) => click({ ...o, button: 'left' }),
    rightClick: (o) => click({ ...o, button: 'right' }),
    setMotionStyle,
    getShapeMarkup: () => SHAPE_SVGS[config.shape],
    getShapePaintStyle: () => ({
      '--pointing-cursor-fill': config.fill,
      '--pointing-cursor-stroke': config.stroke,
    }),
    getInteraction: () => ({
      pressed: interaction.getState() !== 'idle',
      button: interaction.getButton(),
      pressScale: interaction.getPressScale(),
    }),
    mount,
    destroy,
    setOptions,
    getOptions: () => ({ ...config }),
    paint,
  }
}
